ALTER TABLE dataflow ADD COLUMN route character varying;
UPDATE dataflow SET route = orignation || ' -> ' || destnation 
WHERE orignation != destnation 
  AND orignation IS NOT NULL 
  AND destnation IS NOT NULL;

ALTER TABLE dataflow ADD COLUMN route VARCHAR;
UPDATE dataflow SET route = orignation || ' -> ' || destnation 
WHERE orignation IS NOT NULL 
  AND destnation IS NOT NULL 
  AND orignation <> destnation;
